%% |a lawful scripted completion comes back unchanged| example |the model says one word| — laws/generation.lawspec:652
law_a_lawful_scripted_completion_comes_back__the_model_says_one_word() ->
    {Schema, Symbols} = lawspec_data:context(),
    lawspec_beam_effects:with_scope(
        Schema,
        #{
            <<"cake.laws.generation::ability::Generation">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end,
            <<"cake.laws.generation::ability::Provider">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end
        },
        fun(ExampleSchema) ->
            Text = <<"Hello">>,
            Finish = make_stop([], ExampleSchema),
            Counts = make_counts([12, 1, 13], ExampleSchema),
            ReplyModel = <<"gpt-4o-mini-2024-07-18">>,
            Messages = make_cons_2(
                [make_message([make_user([], ExampleSchema), <<"Hi">>], ExampleSchema), []],
                ExampleSchema
            ),
            Model = <<"gpt-4o-mini">>,
            lawspec_beam_runtime:require(
                law_a_lawful_scripted_completion_comes_back(
                    ExampleSchema,
                    Symbols,
                    [Text, Finish, Counts, ReplyModel, Messages, Model]
                ),
                ?LAW_A_LAWFUL_SCRIPTED_COMPLETION_COMES_BACK
            ),
            lawspec_beam_runtime:assert_equal(
                lawspec_definitions:answer(
                    ExampleSchema,
                    Symbols,
                    make_completes(
                        [
                            lawspec_definitions:draft_of(
                                ExampleSchema,
                                Symbols,
                                Text,
                                Finish,
                                Counts,
                                ReplyModel
                            )
                        ],
                        ExampleSchema
                    ),
                    Messages,
                    Model
                ),
                make_right(
                    [
                        make_completion(
                            [
                                <<"Hello">>,
                                make_stop([], ExampleSchema),
                                make_usage([12, 1, 13], ExampleSchema),
                                <<"gpt-4o-mini-2024-07-18">>
                            ],
                            ExampleSchema
                        )
                    ],
                    ExampleSchema
                ),
                <<"|a lawful scripted completion comes back unchanged| example |the model says one word| — laws/generation.lawspec:652"/utf8>>
            )
        end
    ).

