-define(LAW_LAWFUL_SCRIPTED_JSON_COMES_BACK_WHEN_IT_FITS_THE,
    <<"cake.laws.generation::|lawful scripted JSON comes back when it fits the schema|">>
).

%% |lawful scripted JSON comes back when it fits the schema| — laws/generation.lawspec:664
%% Scripted with JSON in a lawful completion, the fake's complete_json
%%     answers with exactly that completion and JSON when the JSON fits the
%%     schema asked for, and with a malformed-JSON failure when it does not.
%% for all (parsed :: cake.laws.generation::type::Parsed) (schema :: cake.laws.generation::type::Schema) (messages :: List (cake.laws.prompt_context::type::Message)) (model :: Text) => (if fits schema parsed then (answerJson (saysJson parsed) messages model schema == Either::Right(scriptedJson parsed)) else isMalformedJson (answerJson (saysJson parsed) messages model schema)) = true end for all
law_lawful_scripted_json_comes_back_when_it_fits_the(
    Schema,
    Symbols,
    [Parsed, Schema_2, Messages, Model]
) ->
    lawspec_beam_runtime:assert_equal(
        case lawspec_definitions:fits(Schema, Symbols, Schema_2, Parsed) of
            true ->
                lawspec_beam_scalar:equal(
                    lawspec_definitions:answer_json(
                        Schema,
                        Symbols,
                        lawspec_definitions:says_json(Schema, Symbols, Parsed),
                        Messages,
                        Model,
                        Schema_2
                    ),
                    make_right_2(
                        [lawspec_definitions:scripted_json(Schema, Symbols, Parsed)],
                        Schema
                    )
                );
            false ->
                lawspec_definitions:is_malformed_json(
                    Schema,
                    Symbols,
                    lawspec_definitions:answer_json(
                        Schema,
                        Symbols,
                        lawspec_definitions:says_json(Schema, Symbols, Parsed),
                        Messages,
                        Model,
                        Schema_2
                    )
                )
