%% |lawful scripted JSON comes back when it fits the schema| example |an atomic decomposition| — laws/generation.lawspec:693
law_lawful_scripted_json_comes_back_when_it_fits_the__an_atomic_decomposition() ->
    {Schema, Symbols} = lawspec_data:context(),
    lawspec_beam_effects:with_scope(
        Schema,
        #{
            <<"cake.laws.generation::ability::Generation">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end,
            <<"cake.laws.generation::ability::Provider">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end
        },
        fun(ExampleSchema) ->
            Parsed = make_decomposed(
                [
                    make_decomposition_json(
                        [make_present([true], ExampleSchema), make_absent([], ExampleSchema)],
                        ExampleSchema
                    )
                ],
                ExampleSchema
            ),
            Schema_2 = make_decomposition_schema([], ExampleSchema),
            Messages = [],
            Model = <<"gpt-4o-mini">>,
            lawspec_beam_runtime:require(
                law_lawful_scripted_json_comes_back_when_it_fits_the(
                    ExampleSchema,
                    Symbols,
                    [Parsed, Schema_2, Messages, Model]
