                ?LAW_LAWFUL_SCRIPTED_JSON_COMES_BACK_WHEN_IT_FITS_THE
            ),
            lawspec_beam_runtime:assert_equal(
                lawspec_beam_schema:match(
                    lawspec_definitions:answer_json(
                        ExampleSchema,
                        Symbols,
                        lawspec_definitions:says_json(ExampleSchema, Symbols, Parsed),
                        Messages,
                        Model,
                        Schema_2
                    ),
                    #{
                        <<"Either::Left">> => fun([_RailwayError0]) -> false end,
                        <<"Either::Right">> => fun([_RailwayValue1]) -> true end
                    }
                ),
                true,
                <<"|lawful scripted JSON comes back when it fits the schema| example |an atomic decomposition| — laws/generation.lawspec:693"/utf8>>
            ),
            lawspec_beam_runtime:assert_equal(
                lawspec_beam_schema:match(
                    lawspec_definitions:answer_json(
                        ExampleSchema,
                        Symbols,
                        lawspec_definitions:says_json(ExampleSchema, Symbols, Parsed),
                        Messages,
                        Model,
                        make_ircot_schema([], ExampleSchema)
                    ),
                    #{
                        <<"Either::Left">> => fun([_RailwayError0]) -> false end,
                        <<"Either::Right">> => fun([_RailwayValue1]) -> true end
                    }
                ),
                false,
                <<"|lawful scripted JSON comes back when it fits the schema| example |an atomic decomposition| — laws/generation.lawspec:695"/utf8>>
