-define(LAW_A_SCRIPTED_FAILURE_COMES_BACK_AS_THE_FAILURE,
    <<"cake.laws.generation::|a scripted failure comes back as the failure|">>
).

%% |a scripted failure comes back as the failure| — laws/generation.lawspec:700
%% Scripted with a failure, the fake answers either operation with exactly
%%     that failure.
%% for all (error :: cake.laws.generation::type::GenerationError) (schema :: cake.laws.generation::type::Schema) (messages :: List (cake.laws.prompt_context::type::Message)) (model :: Text) => answer (cake.laws.generation::type::Reply::Errors(error)) messages model = Either::Left(error) and answerJson (cake.laws.generation::type::Reply::Errors(error)) messages model schema = Either::Left(error) end for all
law_a_scripted_failure_comes_back_as_the_failure(
    Schema,
    Symbols,
    [Error, Schema_2, Messages, Model]
) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:answer(Schema, Symbols, make_errors([Error], Schema), Messages, Model),
        make_left([Error], Schema),
        ?LAW_A_SCRIPTED_FAILURE_COMES_BACK_AS_THE_FAILURE
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:answer_json(
                Schema,
                Symbols,
                make_errors([Error], Schema),
                Messages,
                Model,
                Schema_2
            ),
            make_left_2([Error], Schema),
            ?LAW_A_SCRIPTED_FAILURE_COMES_BACK_AS_THE_FAILURE
        )).

law_a_scripted_failure_comes_back_as_the_failure_case(BaseSchema, Symbols, Values) ->
    lawspec_beam_effects:with_scope(
        BaseSchema,
        #{
            <<"cake.laws.generation::ability::Generation">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end,
            <<"cake.laws.generation::ability::Provider">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end
        },
        fun(Schema) -> law_a_scripted_failure_comes_back_as_the_failure(Schema, Symbols, Values) end
    ).

