-define(LAW_SCRIPTED_REPLIES_ARE_ANSWERED_IN_ORDER_ONE_PER,
    <<"cake.laws.generation::|scripted replies are answered in order, one per request|">>
).

%% |scripted replies are answered in order, one per request| — laws/generation.lawspec:738
%% The fake answers its first request with the first reply it was given,
%%     the second with the second, and so on; a request made after the script
%%     has run out is a provider-error failure.
%% for all (replies :: List (cake.laws.generation::type::Reply)) (messages :: List (cake.laws.prompt_context::type::Message)) (model :: Text) => scriptedRun replies messages model = Append(textAnswers replies, List::Cons(Either::Left(scriptExhausted unitValue), List::Nil())) end for all
law_scripted_replies_are_answered_in_order_one_per(Schema, Symbols, [Replies, Messages, Model]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:scripted_run(Schema, Symbols, Replies, Messages, Model),
        lawspec_beam_runtime:helper(
            <<"append">>,
            [
                lawspec_definitions:text_answers(Schema, Symbols, Replies),
                make_cons(
                    [
                        make_left(
                            [lawspec_definitions:script_exhausted(Schema, Symbols, ls_unit)],
                            Schema
                        ),
                        []
                    ],
                    Schema
                )
            ],
            [
                <<"List Either (cake.laws.generation::type::GenerationError) (cake.laws.generation::type::Completion)">>,
                <<"List Either (cake.laws.generation::type::GenerationError) (cake.laws.generation::type::Completion)">>
            ],
            64
        ),
        ?LAW_SCRIPTED_REPLIES_ARE_ANSWERED_IN_ORDER_ONE_PER
    ).

law_scripted_replies_are_answered_in_order_one_per_case(BaseSchema, Symbols, Values) ->
    lawspec_beam_effects:with_scope(
        BaseSchema,
        #{
            <<"cake.laws.generation::ability::Generation">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end,
            <<"cake.laws.generation::ability::Provider">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.generation::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end
        },
        fun(Schema) ->
            law_scripted_replies_are_answered_in_order_one_per(Schema, Symbols, Values)
        end
    ).

