-define(LAW_EACH_REQUEST_IS_ONE_CALL_OF_THE_OPERATION_ASKED,
    <<"cake.laws.generation::|each request is one call of the operation asked for|">>
).

%% |each request is one call of the operation asked for| — laws/generation.lawspec:757
%% Under a recording, a request with no schema is one call of complete and
%%     none of complete_json, and a request with a schema the reverse, so
%%     specifications that count calls count requests.
%% for all (request :: cake.laws.generation::type::Request) => let it = match (request) { cake.laws.generation::type::Request::Request lawspecFieldreply lawspecFieldschema lawspecFieldmessages lawspecFieldmodel -> lawspecFieldschema } in match (it) { Maybe::Absent  -> ((asked request And (calls of complete == 1)) And (calls of completeJson == 0)); Maybe::Present _lawspecSelection0x0 -> ((asked request And (calls of complete == 0)) And (calls of completeJson == 1)) } = true end for all
law_each_request_is_one_call_of_the_operation_asked(Schema, Symbols, [Request]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_runtime:bind(
            lawspec_beam_schema:match(
                Request,
                #{
                    <<"cake.laws.generation::type::Request::Request">> => fun(
                        [_Reply, Schema_2, _Messages, _Model]
                    ) ->
                        Schema_2
                    end
                }
            ),
            fun(It) ->
                lawspec_beam_schema:match(
                    It,
                    #{
                        <<"Maybe::Absent">> => fun([]) ->
                            ((lawspec_definitions:asked(
                                Schema,
                                Symbols,
                                Request
                            ) andalso
                                (lawspec_beam_effects:count_calls(
                                    Schema,
                                    <<"cake.laws.generation::ability::Generation">>,
                                    <<"complete">>,
                                    any
                                ) =:=
                                    1)) andalso
                                (lawspec_beam_effects:count_calls(
                                    Schema,
                                    <<"cake.laws.generation::ability::Generation">>,
                                    <<"completeJson">>,
                                    any
                                ) =:= 0))
                        end,
                        <<"Maybe::Present">> => fun([_Selection]) ->
                            ((lawspec_definitions:asked(
                                Schema,
                                Symbols,
                                Request
                            ) andalso
                                (lawspec_beam_effects:count_calls(
                                    Schema,
                                    <<"cake.laws.generation::ability::Generation">>,
                                    <<"complete">>,
                                    any
                                ) =:=
                                    0)) andalso
                                (lawspec_beam_effects:count_calls(
                                    Schema,
                                    <<"cake.laws.generation::ability::Generation">>,
                                    <<"completeJson">>,
                                    any
                                ) =:= 1))
                        end
                    }
                )
            end
        ),
        true,
        ?LAW_EACH_REQUEST_IS_ONE_CALL_OF_THE_OPERATION_ASKED
    ).

law_each_request_is_one_call_of_the_operation_asked_case(BaseSchema, Symbols, Values) ->
    lawspec_beam_effects:with_scope(
        BaseSchema,
        #{
            <<"cake.laws.generation::ability::Generation">> => fun(_FactorySchema) ->
                lawspec_beam_effects:recording(
                    _FactorySchema,
                    lawspec_beam_effects:shared(
                        _FactorySchema,
                        <<"cake.laws.generation::handler::scripted">>,
                        fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                    )
                )
            end,
            <<"cake.laws.generation::ability::Provider">> => fun(_FactorySchema) ->
                lawspec_beam_effects:recording(
                    _FactorySchema,
                    lawspec_beam_effects:shared(
                        _FactorySchema,
                        <<"cake.laws.generation::handler::scripted">>,
                        fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                    )
                )
            end
        },
        fun(Schema) ->
            law_each_request_is_one_call_of_the_operation_asked(Schema, Symbols, Values)
        end
    ).

