%% Generation: |a successful completion never has empty text| [scripted] — laws/generation.lawspec:206
%% Whatever the provider says, a completion that succeeds has text. A
%%       handler reports a reply with none as a failure (an empty_response
%%       error in Cake), never as a success whose text is empty. Generated text
%%       is seldom empty, so the law asks twice: with the reply as generated,
%%       and with the same reply emptied of its text.
%% for all (request :: cake.laws.generation::type::Request) => hasText (completed request) = true and hasText (completed (silenced request)) = true end for all
law_generation_a_successful_completion_never_has_2(Schema, Symbols, [Request]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:has_text(
            Schema,
            Symbols,
            lawspec_definitions:completed(Schema, Symbols, Request)
        ),
        true,
        ?LAW_GENERATION_A_SUCCESSFUL_COMPLETION_NEVER_HAS_2
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:has_text(
                Schema,
                Symbols,
                lawspec_definitions:completed(
                    Schema,
                    Symbols,
                    lawspec_definitions:silenced(Schema, Symbols, Request)
                )
            ),
            true,
            ?LAW_GENERATION_A_SUCCESSFUL_COMPLETION_NEVER_HAS_2
        )).

