%% Generation: |usage token counts are never negative| [native] — laws/generation.lawspec:237
%% Whatever counts the provider reports, a completion that succeeds
%%       carries input, output and total token counts of zero or more.
%% for all (request :: cake.laws.generation::type::Request) => let it = completed request in match (it) { Maybe::Absent  -> true; Maybe::Present _lawspecSelection0x0 -> countsNotNegative (match (_lawspecSelection0x0) { cake.laws.generation::type::Completion::Completion lawspecFieldtext lawspecFieldfinishReason lawspecFieldusage lawspecFieldmodel -> lawspecFieldusage }) } = true end for all
law_generation_usage_token_counts_are_never_negative(Schema, Symbols, [Request]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_runtime:bind(
            lawspec_definitions:completed(Schema, Symbols, Request),
            fun(It) ->
                lawspec_beam_schema:match(
                    It,
                    #{
                        <<"Maybe::Absent">> => fun([]) -> true end,
                        <<"Maybe::Present">> => fun([Selection]) ->
                            lawspec_definitions:counts_not_negative(
                                Schema,
                                Symbols,
                                lawspec_beam_schema:match(
                                    Selection,
                                    #{
                                        <<"cake.laws.generation::type::Completion::Completion">> => fun(
                                            [_Text, _FinishReason, Usage, _Model]
                                        ) ->
                                            Usage
                                        end
                                    }
                                )
                            )
                        end
                    }
                )
            end
        ),
        true,
        ?LAW_GENERATION_USAGE_TOKEN_COUNTS_ARE_NEVER_NEGATIVE
    ).

